function part(o){if(R.opt&&!R.opt.fx&&Math.random()<.7)return;if(P.length>520)P.splice(0,80);P.push(Object.assign({vx:0,vy:0,grav:0,drag:.98,life:1,size:10,col:'rgba(255,160,40,1)',add:1,t:0,shrink:1},o))}
function burst(x,y,n,col,sp=160,size=10,life=.6,grav=0){if(R.opt&&!R.opt.fx)n=Math.ceil(n*.3);for(let i=0;i<n;i++){const a=Math.random()*6.283,v=rnd(.3,1)*sp;part({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,col,size:rnd(.5,1.2)*size,life:rnd(.6,1)*life,grav})}}
function ring(x,y,col,r0,r1,life,width=6,squash=1){FX.push({k:'ring',x,y,col,r0,r1,life,t:0,width,squash})}
function dmgText(x,y,v,o={}){if(R.lvT!=null&&R.lvT<1.4&&!o.heal){const L=AS.get('lina');if(L&&Math.abs(x-L.x)<90&&y<L.y+20&&y>L.y-UNIT_H-90)return}if(R.opt&&!R.opt.dmg&&!o.heal)return;if(R.cut&&R.cut.t<1.25&&R.cutPin==null)return;const kind=o.heal?'h':o.ally?'a':'d';if(o.label&&TXT.some(t=>t.label&&t.t<.55&&Math.abs(t.x-x)<70&&Math.abs(t.y-y)<70))return;if(!o.label&&!o.crit&&!o.heal&&TXT.length>=12&&v<(TXT.reduce((a,t)=>a+(t.v||0),0)/TXT.length)*.5)return;const m=!o.label&&o.key&&TXT.find(t=>t.key===o.key&&t.kind===kind&&t.t<(o.boss?.6:.28));if(m){m.v+=v;m.t=Math.min(m.t,.06);m.crit=m.crit||o.crit;m.n=(m.n||1)+1;m.bump=0;if(o.col&&!m.col)m.col=o.col;return}
  const near=TXT.filter(t=>Math.abs(t.x-x)<46&&t.t<.6).length;TXT.push({label:o.label,x:x+rnd(-20,20)+(near%2?1:-1)*near*10,y:y-Math.min(near,4)*18-rnd(0,8),v,t:0,life:o.heal?1:1.05,crit:o.crit,heal:o.heal,ally:o.ally,key:o.key,kind,n:1,col:o.col,life:o.crit?1.2:(o.heal?1:1.05)});if(TXT.length>12)TXT.shift()}
R.fmt=n=>{n=Math.floor(n);return n>=1e9?(n/1e9).toFixed(1)+'B':n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e4?(n/1e3).toFixed(1)+'K':n.toLocaleString()};
