  if(sp.k=='charm'){tg.forEach((e,i)=>{const t=ES.get(e);if(!t)return;hit(()=>{t.conf=1.8;for(let j=0;j<6;j++)part({x:t.x+rnd(-14,14),y:t.y-UNIT_H-rnd(0,10),vx:rnd(-30,30),vy:-rnd(30,80),grav:-10,col:'rgba(255,110,190,1)',size:rnd(8,13),life:1.1,heart:1,shrink:0});dmgText(t.x,t.y-UNIT_H-20,0,{label:'매혹!'})},220+i*50)});return}
